package com.company.platform;
import com.company.platform.operations.*;
import com.company.platform.storage.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** 正式服务、真实PostgreSQL与双份磁盘对象；故障仅注入本测试新建文件。 */
@EnabledIfEnvironmentVariable(named="IMS_OPERATIONS_CONSOLE_INTEGRATION",matches="yes")
@SpringBootTest(classes=PlatformApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.config.name=platform","server.ssl.enabled=false","platform.operations.enabled=true","platform.operations.schedule-enabled=false","platform.messaging.schedule-enabled=false","platform.file-worker.enabled=false","platform.scan-intake.worker-enabled=false","platform.notifications.schedule-enabled=false","platform.borrow-lifecycle.enabled=false"})
class OperationsConsoleIntegrationTest {
 @DynamicPropertySource static void guard(DynamicPropertyRegistry r){String url=System.getenv("IMS_PLATFORM_DB_URL");if(url==null||!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:55465/ims_platform_dev_[0-9]+"))throw new IllegalStateException("仅允许运维控制台专用隔离库");}
 @Autowired Sql db;@Autowired IdentityService identity;@Autowired Commands commands;@Autowired OperationsConsole service;@Autowired StorageFiles files;@Autowired PlatformTransactionManager manager;
 private Actor admin,employee;
 @BeforeEach void setup(){admin=login(System.getenv("IMS_PLATFORM_ADMIN_NO"));UUID id=UUID.randomUUID();String no="OPS-"+id;db.update("INSERT INTO iam.user_account(id,employee_no,name,department_id,company_email,password_hash,password_setup_required) VALUES(?,?,?,?,?,?,false)",id,no,"运维隔离员工",admin.user().get("departmentId"),no+"@biolink.com",Crypto.password("123456"));employee=login(no);files.get();}
 private Actor login(String no){return identity.authenticate(identity.login(Sql.map("employeeNo",no,"password","123456"),UUID.randomUUID(),"ops-test-"+UUID.randomUUID()).get("token").toString());}
 private Commands.Context context(Actor actor,String type,UUID id,String action,Integer version){var proof=identity.reauthenticate(actor,Sql.map("password","123456","purpose","MANAGE","objectIds",List.of(id.toString()),"scopeItems",List.of(Sql.map("objectType",type,"objectId",id.toString(),"actions",List.of(action)))),UUID.randomUUID());return new Commands.Context(actor,UUID.randomUUID(),UUID.randomUUID(),"TEST "+action+id,proof.get("verificationToken").toString(),version);}
 private Map<String,Object> create(Actor actor,String kind){return create(context(actor,"MAINTENANCE_RUN",ApiController.COLLECTION,"CREATE_MAINTENANCE",null),Sql.map("kind",kind,"reason","本机隔离运维验收"));}
 private Map<String,Object> create(Commands.Context ctx,Map<String,Object> body){return commands.run(ctx,body,"MAINTENANCE_RUN",ApiController.COLLECTION,"CREATE_MAINTENANCE",()->ctx.actor().require("PLATFORM.OPERATIONS_MANAGE"),()->service.create(ctx,body,null),id->service.run(ctx.actor(),id));}
 private void status(int code,org.junit.jupiter.api.function.Executable call){assertEquals(code,assertThrows(ApiFault.class,call).status);}
 private Map<String,Object> run(UUID id){return db.required("SELECT * FROM ops.maintenance_run WHERE id=?",id);}
 private void complete(UUID id){for(int i=0;i<60&&Set.of("QUEUED","RUNNING").contains(run(id).get("state"));i++)service.tick();assertFalse(Set.of("QUEUED","RUNNING").contains(run(id).get("state")));}
 /** 原件登记与磁盘字节使用正式双副本写适配器，摘要由真实字节计算。 */
 private UUID object(byte[] bytes){try{UUID id=UUID.randomUUID();String sha=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)),key=files.get().receive(new java.io.ByteArrayInputStream(bytes),bytes.length,sha);db.update("INSERT INTO storage.object(id,module,storage_key,sha256,byte_size,media_type,original_name,object_kind,state,created_by,check_result_ref) VALUES(?,'DRIVE',?,?,?,'text/plain','不应公开的测试文件名','ORIGINAL','READY',?,'OPS_TEST')",id,key,sha,bytes.length,admin.userId());return id;}catch(Exception e){throw new RuntimeException(e);}}
 @Test void ordinaryUserCannotReadOrQueueOperations(){status(403,()->service.overview(employee));status(403,()->service.list(employee,"jobs",Map.of()));status(403,()->create(employee,"BACKUP"));}
 @Test void operationsCapabilityDoesNotIncludeBackupOrRestore(){db.update("INSERT INTO iam.role_permission(role_id,permission_id,scope_policy,effect,changed_by) SELECT r.id,p.id,'COMPANY','ALLOW',? FROM iam.role r JOIN iam.permission p ON p.code='PLATFORM.OPERATIONS_MANAGE' WHERE r.module='PLATFORM' AND r.code='MEMBER' ON CONFLICT DO NOTHING",admin.userId());db.update("INSERT INTO iam.user_role(id,user_id,role_id,valid_from,assigned_by,module,role_code) SELECT ?,?,id,CURRENT_TIMESTAMP,?,'PLATFORM','MEMBER' FROM iam.role WHERE module='PLATFORM' AND code='MEMBER'",UUID.randomUUID(),employee.userId(),admin.userId());employee=identity.background(employee.sessionId());assertNotNull(service.overview(employee));status(403,()->create(employee,"BACKUP"));status(403,()->create(employee,"RESTORE_VERIFY"));}
 @Test void queueReplayDoesNotDuplicateAndRejectsChangedPayload(){var ctx=context(admin,"MAINTENANCE_RUN",ApiController.COLLECTION,"CREATE_MAINTENANCE",null);var body=Sql.map("kind","BACKUP","reason","幂等验收");UUID id=(UUID)create(ctx,body).get("id");assertEquals(id,create(ctx,body).get("id"));assertEquals("WAITING_WINDOW",run(id).get("state"));body.put("reason","不同内容");status(409,()->create(ctx,body));}
 @Test void externalPathsAndForgedResultAreRejected(){var body=Sql.map("kind","BACKUP","reason","输入边界","output","D:/existing");status(400,()->create(context(admin,"MAINTENANCE_RUN",ApiController.COLLECTION,"CREATE_MAINTENANCE",null),body));status(400,()->create(admin,"RESTORE_VERIFY"));}
 @Test void checksReportUnavailableServicesWithoutClaimingProtected(){UUID id=(UUID)create(admin,"PROTECTION_CHECK").get("id");complete(id);var result=service.run(admin,id);String summary=Crypto.json(result.get("summary"));assertTrue(summary.contains("DEGRADED"));assertFalse(summary.contains("D:/"));assertFalse(summary.contains("123456"));assertEquals("SUCCEEDED",run(id).get("state"));assertTrue(db.count("SELECT count(*) FROM ops.security_alert WHERE kind='OPS_PROTECTION'")>0);}
 @Test void actualCopiesPassAndMutatedSecondaryFailsThenNewRunRecovers()throws Exception{byte[] bytes="本机双副本测试内容".getBytes(java.nio.charset.StandardCharsets.UTF_8);UUID object=object(bytes),first=(UUID)create(admin,"REPLICA_CHECK").get("id");complete(first);assertEquals("PASSED",db.required("SELECT state FROM ops.replica_check WHERE object_id=?",object).get("state"));String key=db.required("SELECT storage_key FROM storage.object WHERE id=?",object).get("storage_key").toString();Path secondary=Path.of(System.getenv("IMS_PLATFORM_STORAGE_SECONDARY"),key);byte[] broken=bytes.clone();broken[0]^=1;Files.write(secondary,broken);try{UUID failed=(UUID)create(admin,"REPLICA_CHECK").get("id");complete(failed);assertEquals("FAILED",run(failed).get("state"));assertEquals("FAILED",db.required("SELECT state FROM ops.replica_check WHERE object_id=?",object).get("state"));}finally{Files.write(secondary,bytes);}UUID repaired=(UUID)create(admin,"REPLICA_CHECK").get("id");complete(repaired);assertEquals("SUCCEEDED",run(repaired).get("state"));assertEquals("PASSED",db.required("SELECT state FROM ops.replica_check WHERE object_id=?",object).get("state"));assertFalse(Crypto.json(service.list(admin,"replicas",Map.of())).contains("测试文件名"));}
 @Test void cancellationChecksVersionAndCannotRepeat(){UUID id=(UUID)create(admin,"BACKUP").get("id");var bad=context(admin,"MAINTENANCE_RUN",id,"CANCEL_MAINTENANCE",99);status(409,()->new TransactionTemplate(manager).execute(tx->service.cancel(bad,id)));var ctx=context(admin,"MAINTENANCE_RUN",id,"CANCEL_MAINTENANCE",1);var body=Sql.map("reason","取消本次合成任务");assertEquals("CANCELLED",commands.run(ctx,body,"MAINTENANCE_RUN",id,"CANCEL_MAINTENANCE",()->admin.require("PLATFORM.OPERATIONS_MANAGE"),()->service.cancel(ctx,id),key->service.run(admin,key)).get("state"));assertEquals("CANCELLED",run(id).get("state"));status(409,()->new TransactionTemplate(manager).execute(tx->service.cancel(context(admin,"MAINTENANCE_RUN",id,"CANCEL_MAINTENANCE",2),id)));}
 @Test void retryKeepsFailedRecordAndCreatesNewId(){UUID id=(UUID)create(admin,"BACKUP").get("id");db.update("UPDATE ops.maintenance_run SET state='FAILED',error_code='TEST_FAILURE' WHERE id=?",id);var ctx=context(admin,"MAINTENANCE_RUN",id,"RETRY_MAINTENANCE",1);var body=Sql.map("reason","修复后重试");var next=commands.run(ctx,body,"MAINTENANCE_RUN",id,"RETRY_MAINTENANCE",()->admin.require("PLATFORM.OPERATIONS_MANAGE"),()->service.retry(ctx,id,body),key->service.run(admin,key));assertNotEquals(id,next.get("id"));assertEquals("FAILED",run(id).get("state"));assertEquals(id,run((UUID)next.get("id")).get("parent_run_id"));}
 @Test void revokedQueuedTaskDoesNotExecute(){UUID id=(UUID)create(admin,"REPLICA_CHECK").get("id");new TransactionTemplate(manager).executeWithoutResult(tx->identity.invalidate(admin.userId(),"OPS_TEST_REVOKE",UUID.randomUUID()));complete(id);assertEquals("REQUESTER_AUTHORIZATION_INVALID",run(id).get("error_code"));}
 @Test void expiredLeaseBecomesManualWithoutPretendingSuccess(){UUID id=(UUID)create(admin,"BACKUP").get("id");db.update("UPDATE ops.maintenance_run SET state='RUNNING',lease_token=?,lease_until=CURRENT_TIMESTAMP-interval '1 second' WHERE id=?",UUID.randomUUID(),id);service.tick();assertEquals("MANUAL",run(id).get("state"));assertEquals("EXECUTION_RESULT_UNKNOWN",run(id).get("error_code"));}
 @Test void backupPlanSchedulesOncePerDayAndPreservesDefaultThirtyDays(){var existing=db.required("SELECT * FROM ops.backup_plan");var ctx=context(admin,"BACKUP_PLAN",ApiController.COLLECTION,"SAVE_BACKUP_PLAN",((Number)existing.get("row_version")).intValue());var body=Sql.map("enabled",true,"hourShanghai",0,"retentionDays",30,"reason","每日计划验收");commands.run(ctx,body,"BACKUP_PLAN",ApiController.COLLECTION,"SAVE_BACKUP_PLAN",()->admin.require("PLATFORM.BACKUP_MANAGE"),()->service.plan(ctx,body),id->Sql.map("id",id));service.scheduleBackup();service.scheduleBackup();assertEquals(1,db.count("SELECT count(*) FROM ops.maintenance_run WHERE schedule_key=?","BACKUP:"+java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"))));assertEquals(30,db.count("SELECT retention_days FROM ops.backup_plan"));db.update("UPDATE ops.backup_plan SET enabled=false");}
 /** 已排队也必须服从个人明确拒绝；到期后的拒绝不永久阻断维护。 */
 @Test void explicitDenyOverridesRoleAllowAndExpiredDenyStopsApplying(){UUID task=(UUID)create(admin,"REPLICA_CHECK").get("id"),deny=UUID.randomUUID();db.update("INSERT INTO iam.permission_assignment(id,user_id,permission_id,scope_type,effect,valid_from,granted_by) SELECT ?,?,id,'MODULE','DENY',CURRENT_TIMESTAMP,? FROM iam.permission WHERE code='PLATFORM.OPERATIONS_MANAGE'",deny,admin.userId(),admin.userId());try{assertFalse(service.authorized(run(task)));complete(task);assertEquals("REQUESTER_AUTHORIZATION_INVALID",run(task).get("error_code"));db.update("UPDATE iam.permission_assignment SET valid_until=CURRENT_TIMESTAMP-interval '1 second',valid_from=CURRENT_TIMESTAMP-interval '1 day' WHERE id=?",deny);assertTrue(service.authorized(run(task)));}finally{db.update("UPDATE iam.permission_assignment SET state='REVOKED' WHERE id=?",deny);}}

}
